def max_people_stay(t, test_cases):
    results = []
    for n in test_cases:
        if n == 1:
            results.append(1)
        else:
            results.append(n - (n // 2) - 1)
    return results

# Read input
t = int(input().strip())
test_cases = [int(input().strip()) for _ in range(t)]

# Get the results
results = max_people_stay(t, test_cases)

# Print results
for result in results:
    print(result)
